def brief(part):
    """A part's rules in a few lines for the 4B ("" for a part without rules)."""
    r = RULES.get(part)
    if not r:
        return ""
    return (f"{part}: {r['job']}; holds {r['content']}. Rules: " + "; ".join(r["rules"])
            + (". Never: " + "; ".join(r["never"]) if r["never"] else "") + f". Phone: {r['phone']}.")


def common():
    return "Premium app rules (every screen):\n" + "\n".join(f"- {c}" for c in COMMON)
